  "story.bees.label": "The bees",
  "story.bees.t1": "Bees carry value",
  "story.bees.t2": "both ways.",
  "story.bees.body": "On every trip they feed the hive and help the meadow grow. That is our job: connecting your business to the nature and people it depends on.",
  "story.bees.tagNature": "Nature & people",
  "story.bees.tagBusiness": "Your business",
